"""F-006 (BR-088, BR-039 clarified) in the image: without a connections key, the gateway is ready
and its connections are seen `key_absent`; `restore-check` proves it on a copy."""

from __future__ import annotations

import json
import re
import time
import uuid

from .conftest import APP_ENV, IMAGE, Stack, docker, http_status, wait_ready


def connection_sql(tag: str) -> str:
    """A provided-token connection written in the database (fake ciphertext: the key is missing)."""
    # hexadecimal tag generated by the test
    return (
        "INSERT INTO node (id, parent_id, level, slug, name, created_at)"  # noqa: S608
        f" VALUES ('n-{tag}', 'org', 'client', 'c-{tag}', 'C', 0);"
        f"INSERT INTO service (id, model, base_url, created_at)"
        f" VALUES ('s-{tag}', 'gitea', 'https://g.example.test', 0);"
        "INSERT OR IGNORE INTO vault_meta (id, envelope_version, key_check)"
        " VALUES (1, 1, zeroblob(16));"
        "INSERT INTO connection (id, client_node_id, name, prefix, service_id, kind, state,"
        f" tokens_enc, created_at) VALUES ('x-{tag}', 'n-{tag}', 'gitea', 'p{tag[:6]}',"
        f" 's-{tag}', 'provided', 'active', zeroblob(40), 0);"
    )


def test_br_088_container_without_connections_key_is_ready(name: str) -> None:
    docker("run", "-d", "--name", name, "--read-only", "-v", f"{name}:/data", *APP_ENV, IMAGE)
    wait_ready(name)
    tag = uuid.uuid4().hex[:8]
    code = (
        "import sqlite3\n"
        "c = sqlite3.connect('/data/hullgate.db', isolation_level=None, timeout=5)\n"
        f"c.executescript({connection_sql(tag)!r})\n"
    )
    docker("exec", name, "python", "-c", code)
    assert http_status(name, "http://127.0.0.1:4790/healthz") == 200
    assert http_status(name, "http://127.0.0.1:4790/readyz") == 200
    state = docker("exec", name, "hullgate", "connection", "status", "--json")
    [conn] = json.loads(state.stdout)
    assert (conn["name"], conn["state"], conn["key"]) == (
        f"c-{tag}/gitea",
        "key_absent",
        "key_absent",
    )
    refused = docker(
        "exec", name, "hullgate", "connection", "add", f"c-{tag}/autre", "--service",
        f"s-{tag}", "--application", "app", "--prefix", "zz", check=False,
    )  # fmt: skip
    assert refused.returncode == 1
    assert "key_absent" in refused.stderr
    logs = docker("logs", name, check=False)
    assert "Traceback" not in logs.stdout + logs.stderr


def test_br_039_restore_check_with_connections_sees_key_absent(stack: Stack) -> None:
    stack.sql(connection_sql(uuid.uuid4().hex[:8]))
    time.sleep(0.2)
    backup = stack.ops("backup")
    assert backup.returncode == 0, backup.stdout + backup.stderr
    match = re.search(r"BACKUP: OK (\S+)", backup.stdout)
    assert match
    result = stack.ops("restore-check", match.group(1))
    assert result.returncode == 0, result.stdout + result.stderr
    line = next(x for x in result.stdout.splitlines() if x.startswith("RESTORE-CHECK: OK"))
    found = re.search(r"connections=(\d+) \(key_absent\)", line)
    assert found
    assert int(found.group(1)) >= 1
    tables = json.loads(line.split("tables=", 1)[1])
    assert tables["connection"] >= 1
